content.css:
.mt-root {
  box-sizing: border-box;
  height: 100%;
  display: flex;
  flex-direction: column;
  padding: 16px 20px 12px;
  background: #16101F;
  border: 1px solid #2E2340;
  border-radius: 16px;
  color: #F4ECFB;
  font-family: "Segoe UI", Arial, sans-serif;
  font-size: 14px;
  overflow: hidden;
}
.mt-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
  margin-bottom: 10px;
}
.mt-title {
  font-size: 1.3em;
  font-weight: 700;
}
.mt-subtitle {
  margin-top: 2px;
  font-size: 0.85em;
  color: #8E80A0;
}
.mt-tools {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: none;
}
.mt-count {
  font-size: 0.85em;
  color: #8E80A0;
  white-space: nowrap;
}
.mt-clear {
  font: inherit;
  font-size: 0.8em;
  color: #F28DB2;
  background: rgba(242, 141, 178, 0.1);
  border: 1px solid rgba(242, 141, 178, 0.4);
  border-radius: 999px;
  padding: 3px 12px;
  cursor: pointer;
}
.mt-search,
.mt-filter {
  font: inherit;
  color: #F4ECFB;
  background: #1E1629;
  border: 1px solid rgba(224, 176, 255, 0.22);
  border-radius: 8px;
  outline: none;
}
.mt-search::placeholder,
.mt-filter::placeholder {
  color: #6F6380;
}
.mt-search:focus,
.mt-filter:focus {
  border-color: #E0B0FF;
  box-shadow: 0 0 0 2px rgba(224, 176, 255, 0.18);
}
.mt-search {
  width: 220px;
  padding: 6px 12px;
  font-size: 0.9em;
}
.mt-scroll {
  flex: 1;
  min-height: 0;
  overflow: auto;
  scrollbar-width: thin;
  scrollbar-color: #5D4A78 transparent;
}
.mt-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
}
.mt-head th {
  position: sticky;
  top: 0;
  z-index: 2;
  background: #16101F;
  text-align: left;
  font-size: 0.75em;
  font-weight: 600;
  letter-spacing: 1.2px;
  text-transform: uppercase;
  color: #8E80A0;
  padding: 4px 10px 8px;
  white-space: nowrap;
  cursor: pointer;
  user-select: none;
}
.mt-head th:hover,
.mt-head th.mt-sorted {
  color: #E0B0FF;
}
.mt-filters th {
  position: sticky;
  top: 30px;
  z-index: 2;
  background: #16101F;
  padding: 0 6px 8px;
  border-bottom: 1px solid rgba(224, 176, 255, 0.22);
}
.mt-filter {
  box-sizing: border-box;
  width: 100%;
  min-width: 60px;
  padding: 4px 8px;
  font-size: 0.8em;
}
.mt-filter.mt-active {
  border-color: #E0B0FF;
  background: rgba(224, 176, 255, 0.1);
}
.mt-select {
  min-width: 90px;
  padding-right: 24px;
  cursor: pointer;
  appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, #E0B0FF 50%), linear-gradient(135deg, #E0B0FF 50%, transparent 50%);
  background-position: calc(100% - 13px) 55%, calc(100% - 8px) 55%;
  background-size: 5px 5px;
  background-repeat: no-repeat;
}
.mt-select option {
  background: #1E1629;
  color: #F4ECFB;
}
.mt-radios {
  display: flex;
  gap: 4px;
  flex-wrap: nowrap;
}
.mt-radio {
  cursor: pointer;
}
.mt-radio input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}
.mt-radio span {
  display: inline-block;
  padding: 3px 9px;
  border: 1px solid rgba(224, 176, 255, 0.22);
  border-radius: 999px;
  background: #1E1629;
  color: #8E80A0;
  font-size: 0.75em;
  font-weight: 600;
  letter-spacing: 0.3px;
  white-space: nowrap;
  text-transform: none;
}
.mt-radio input:checked + span {
  border-color: #E0B0FF;
  background: #E0B0FF;
  color: #16101F;
}
.mt-radio input:focus-visible + span {
  box-shadow: 0 0 0 2px rgba(224, 176, 255, 0.35);
}
.mt-radio:hover span {
  color: #F4ECFB;
}
.mt-table td {
  padding: 8px 10px;
  border-bottom: 1px solid rgba(224, 176, 255, 0.1);
  color: #E6DAF2;
  white-space: nowrap;
}
.mt-table th.mt-right,
.mt-table td.mt-right {
  text-align: right;
  font-variant-numeric: tabular-nums;
}
.mt-table tbody tr {
  cursor: pointer;
  transition: background 0.12s, opacity 0.12s;
}
.mt-table tbody tr:hover td {
  background: rgba(224, 176, 255, 0.06);
}
.mt-table tbody tr.mt-selected td {
  background: rgba(224, 176, 255, 0.14);
  color: #F4ECFB;
}
.mt-table tbody tr.mt-dimmed {
  opacity: 0.4;
}
.mt-pill {
  display: inline-block;
  padding: 1px 10px;
  border: 1px solid;
  border-radius: 999px;
  font-size: 0.8em;
  font-weight: 600;
}
.mt-chip {
  display: inline-block;
  margin: 1px 4px 1px 0;
  padding: 1px 7px;
  border: 1px solid rgba(242, 141, 178, 0.3);
  border-radius: 5px;
  background: rgba(242, 141, 178, 0.1);
  color: #F2B5CB;
  font-size: 0.72em;
  letter-spacing: 0.4px;
}
.mt-unknown {
  padding: 1px 6px;
  border: 1px solid #F28DB2;
  border-radius: 4px;
  color: #F28DB2;
  font-size: 0.7em;
  letter-spacing: 1px;
}
.mt-missing {
  color: #6F6380;
}
.mt-negative {
  color: #F28DB2 !important;
}
.mt-empty {
  padding: 24px;
  text-align: center;
  color: #8E80A0;
}
